css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 7px 12px; margin-bottom: 9px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 5px;}
.mz .rec-cuerpo{display: flex; align-items: center; gap: 22px; flex-wrap: wrap;}
.mz .rec-texto{font-size: 14px; line-height: 1.45;}
.mz .rec-texto b{font-size: 17px;}
.mz .rec-op{font-size: 19px; font-weight: 700; font-family: sans-serif; white-space: nowrap;}
.mz .rec-op .x{font-size: 21px;}
.mz .grupos{display: flex; align-items: center; gap: 14px; flex-wrap: wrap; margin-bottom: 4px;}
.mz .grupo{border: 1.6px dashed #000; border-radius: 11px; padding: 5px 8px; display: grid; gap: 5px; justify-content: center;}
.mz .grupo .row{display: flex; gap: 5px;}
.mz .punto{width: 12px; height: 12px; border-radius: 50%; background: #000;}
.mz .grupos .mas-g{font-size: 21px; font-weight: 800; font-family: sans-serif;}
.mz .grupo-vacio{border: 1.6px dashed #000; border-radius: 11px; width: 122px; height: 46px;}
.mz .rejilla{display: inline-grid; gap: 7px; border: 1.6px solid var(--bosque); border-radius: 10px; padding: 8px 10px;}
.mz .rejilla .punto{width: 11px; height: 11px;}
.mz .rejillas-fila{display: flex; align-items: center; gap: 24px; flex-wrap: wrap; margin-bottom: 5px;}
.mz .resp-fila{display: flex; align-items: center; gap: 7px; font-size: 18px; font-weight: 700; font-family: sans-serif; margin-bottom: 5px; flex-wrap: wrap;}
.mz .caja{width: 42px; height: 31px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block;}
.mz .caja.res{width: 54px;}
.mz .resp-fila .sep{font-size: 18px;}
.mz .resp-fila .lead{min-width: 122px; font-size: 17px;}
.mz .resp-fila.ejemplo{background: #ededed; border-radius: 7px; padding: 4px 11px; display: inline-flex;}
.mz .resp-fila.ejemplo .et{font-size: 11.5px; font-family: sans-serif; font-weight: 700; margin-right: 4px;}
.mz .pista{font-family: sans-serif; font-size: 11.5px; font-weight: 600; color: #555; margin: -2px 0 7px;}
.mz .dos-col{display: grid; grid-template-columns: 1fr 1fr; gap: 0 30px;}
